def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    S = np.column_stack([np.ones(n)] + [np.array([s == l for s in feats.stratum], float) for l in labs[1:]])

    def ll(Z):
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            eta = np.clip(Z @ b, -30, 30); mu = 1 / (1 + np.exp(-eta))
            w = mu * (1 - mu) + 1e-9
            H = Z.T @ (Z * w[:, None]) + 1e-6 * np.eye(Z.shape[1])
            step = np.linalg.solve(H, Z.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        eta = np.clip(Z @ b, -30, 30)
        return float(np.sum(y * eta - np.logaddexp(0, eta)))

    def design_mat(sel, extra=()):
        return np.column_stack([S] + [X[:, j] for j in sel] + list(extra))

    R = np.corrcoef(X, rowvar=False)
    sel = []
    base = ll(S)
    while len(sel) < MAX_DRIVERS:
        alpha = (0.05 if not sel else 0.01) / p
        best, bj = None, None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            pv = stats.chi2.sf(2 * (ll(design_mat(sel + [j])) - base), 1)
            if best is None or pv < best: best, bj = pv, j
        if bj is None or best > alpha: break
        sel.append(bj); base = ll(design_mat(sel))
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (base - ll(design_mat(rest))), 1) > 0.01 / p:
                sel = rest; base = ll(design_mat(sel)); changed = True; break
    # all-pairs + squares product screen, 1-df LR given both mains
    npairs = p * (p + 1) / 2
    cands = []
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            mains = list(dict.fromkeys(sel + [a, b]))
            l0 = ll(design_mat(mains))
            l1 = ll(design_mat(mains, [X[:, a] * X[:, b]]))
            pv = stats.chi2.sf(2 * (l1 - l0), 1)
            if pv < 0.01 / npairs: cands.append((pv, a, b))
    cands.sort()
    prods = []
    for pv, a, b in cands:
        if len(prods) >= 2: break
        if any(len({a, b} & {c, d}) for c, d in prods): continue
        prods.append((a, b))
    drivers = list(sel)
    for a, b in prods:
        for j in (a, b):
            if j not in drivers: drivers.append(j)
    drivers = drivers[:MAX_DRIVERS]
    cols = list(dict.fromkeys(sel + [j for ab in prods for j in ab]))
    return Design(drivers=tuple(ids[j] for j in drivers), columns=tuple(ids[j] for j in cols),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

